/** Every number in a solve result, by its dotted path ({ sides: { CA: 5 } } -> { 'sides.CA': 5 }); arrays are skipped. */
export function flatSolve(o, p = '', out = {}) {
  if (typeof o === 'number' && Number.isFinite(o)) out[p] = o;
  else if (o && typeof o === 'object' && !Array.isArray(o)) for (const [k, v] of Object.entries(o)) if (Object.keys(out).length < 200) flatSolve(v, p ? `${p}.${k}` : k, out);
  return out;
}
/** OF.solve for a kind, as an object, or null (some kinds have no solver, or a solver of another shape). */
export function solveOf(OF, kind, data) {
  const f = OF && OF.solve && OF.solve[kind];
  if (typeof f !== 'function') return null;
  try { const r = f(data); return r && typeof r === 'object' && !Array.isArray(r) ? r : null; } catch { return null; }
}
/** A number written for an answer: at most dp decimal places, no trailing zeros. */
export function numText(x, dp = 2) {
  const k = 10 ** Math.max(0, Math.min(6, dp)), r = Math.round((x + Math.sign(x) * 1e-12) * k) / k;
  return String(Object.is(r, -0) ? 0 : r);
}
/** A figure's data for a link (?d=): base64url of its JSON. */
export function encodeData(o) {
  const s = JSON.stringify(o), b = typeof Buffer !== 'undefined' ? Buffer.from(s, 'utf8').toString('base64') : btoa(String.fromCharCode(...new TextEncoder().encode(s)));
  return b.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
/** ?d= back to data (a plain object), or null. */
export function decodeData(s) {
  try {
    const b = String(s || '').replace(/-/g, '+').replace(/_/g, '/');
    if (!b || b.length > 16000) return null;
    const txt = typeof Buffer !== 'undefined' ? Buffer.from(b, 'base64').toString('utf8') : new TextDecoder().decode(Uint8Array.from(atob(b), c => c.charCodeAt(0)));
    const o = JSON.parse(txt);
    return o && typeof o === 'object' && !Array.isArray(o) ? o : null;
  } catch { return null; }
}
